sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.request-modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
}

.request-modal {
  background: #fff;
  border-radius: 6px;
  padding: 28px;
  width: 340px;
}

.request-modal h3 {
  margin: 0 0 14px;
  font-size: 18px;
  color: #333;
}

.modal-meta {
  font-size: 13px;
  color: #777;
  margin-bottom: 16px;
}

.request-modal label {
  font-size: 12.5px;
  color: #555;
  display: block;
  margin-bottom: 6px;
}

.request-modal select {
  width: 100%;
  padding: 8px;
  margin-bottom: 20px;
  border: 1px solid #d4d4d4;
  border-radius: 4px;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.modal-actions button {
  padding: 9px 18px;
  font-size: 13px;
  border-radius: 4px;
  cursor: pointer;
}

.modal-actions .secondary {
  background: #fff;
  border: 1px solid #d4d4d4;
}

.modal-actions .primary {
  background: #e60028;
  color: white;
  border: none;
}
